    player.move(d);
}

function init() {
    ui.onKey((key) => {
        if (key == "w") m("up");
        else if (key == "a") m("left");
        else if (key == "s") m("down");
        else if (key == "d") m("right");
        else if (key == " ") player.attackClosest();
    });
}

